    56  int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    57      register_mib_handlers();
    58
    59      char *filename;
    60      if (asprintf(&filename, "/tmp/libfuzzer-%d.config", getpid()) == -1) {
    61          return 0;
    62      }
    63
    64      FILE *fp = fopen(filename, "wb");
    65      if (!fp) {
    66          free(filename);
    67          return 0;
    68      }
    69      fwrite(data, size, 1, fp);
    70      fclose(fp);
    71
    72      read_config(filename, read_config_get_handlers("snmp"), 0);
    73
    74      unlink(filename);
    75      free(filename);
    76      return 0;
    77  }

